def dehydrate_timedelta(value):
    """ Dehydrator for `timedelta` values.

    :param value:
    :type value: timedelta
    :return:
    """
    if value is None:
        return None
    return value.total_seconds()

def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    if value is None:
        return None
    return value.isoformat()

def keys(self):
    """
    Return the keys of the record.
    :return: list of key names
    """
    return list(self._data.keys())

def protocol_handlers(cls, protocol_version=None):
        """ Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        # Helper to collect handlers from class attributes
        def _collect_handlers():
            handlers = {}
            for attr in getattr(cls, "__dict__", {}).values():
                if isinstance(attr, type) and hasattr(attr, "PROTOCOL"):
                    protocol = getattr(attr, "PROTOCOL", None)
                    if isinstance(protocol, tuple):
                        handlers[protocol] = attr
            return handlers

        # If the class already defines a registry, use it
        if hasattr(cls, "_PROTOCOL_HANDLERS") and isinstance(cls._PROTOCOL_HANDLERS, dict):
            registry = cls._PROTOCOL_HANDLERS
        else:
            registry = _collect_handlers()

        if protocol_version is None:
            return registry

        if not isinstance(protocol_version, tuple):
            raise TypeError("protocol_version must be a tuple of (major, minor)")

        return {protocol_version: registry[protocol_version]} if protocol_version in registry else {}

def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    try:
        return self._index.index(key)
    except ValueError:
        raise KeyError(f"Key {key!r} not found")

def values(self, *keys):
        """ Return the values of the record, optionally filtering to
        include only certain values by index or key.

        :param keys: indexes or keys of the items to include; if none
                     are provided, all values will be included
        :return: list of values
        :rtype: list
        """
        # If no keys are provided, return all values in the record
        if not keys:
            return list(self._items.values())

        # If keys are specified, order the results following the supplied keys
        results = []
        for key in keys:
            if isinstance(key, int):
                # Treat integers as positional indices
                try:
                    results.append(list(self._items.values())[key])
                except IndexError:
                    raise IndexError(f'Index {key} out of range')
            else:
                # Otherwise treat as dictionary keys
                if key in self._items:
                    results.append(self._items[key])
                else:
                    raise KeyError(f'Key {key} not found in record')
        return results

def data(self, *keys):
    """
    Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # If no keys were specified, return all field/value pairs
    if not keys:
        return {name: self[name] for name in getattr(self, "_names", [])}

    names = getattr(self, "_names", [])
    result = {}

    for key in keys:
        # Handle integer index
        if isinstance(key, int):
            length = len(self)
            # Convert negative indices to positive ones
            if key < 0:
                key += length
            if key < 0 or key >= length:
                raise IndexError(f"index {key} out of bounds for size {length}")
            name = names[key]
            result[name] = self[key]
        # Handle named key
        else:
            if hasattr(self, "_names") and key in names:
                result[key] = self[key]
            else:
                # Insert missing keys with None
                result[key] = None

    return result

def point_type(name, fields, srid_map):
    """Dynamically create a Point subclass."""
    # Ensure that the names for the fields are valid identifiers
    if not isinstance(name, str):
        raise TypeError(f"name must be a string, got {type(name).__name__}")
    if not isinstance(fields, (list, tuple)):
        raise TypeError(f"fields must be a list or tuple, got {type(fields).__name__}")
    for f in fields:
        if not isinstance(f, str) or not f.isidentifier():
            raise ValueError(f"Invalid field name: {f!r}")
    if not hasattr(srid_map, "items"):
        raise TypeError("srid_map must be a mapping")
    # Create a new subclass of Point dynamically
    class_attrs = {
        "__slots__": tuple(fields),
        "__srid_map__": dict(srid_map),
    }
    # Optional: a simple __repr__ to display the fields
    def __repr__(self):
        values = ", ".join(f"{name}={getattr(self, name)!r}" for name in fields)
        return f"{name}({values})"
    class_attrs["__repr__"] = __repr__
    return type(name, (Point,), class_attrs)

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    parts = s.split('.')
    nums = []
    for part in parts:
        num_str = ''
        for ch in part:
            if ch.isdigit():
                num_str += ch
            else:
                break
        if num_str:
            nums.append(int(num_str))
        else:
            nums.append(0)
    return tuple(nums)

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        if cache is None:
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
        elif lock is None:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    with lock:
                        return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    with lock:
                        cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return wrapper
    return decorator

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time‑to‑live (TTL) value.
    """
    def decorator(func):
        cache = {}
        lru = []

        def make_key(args, kwargs):
            key = args
            if kwargs:
                items = tuple(sorted(kwargs.items()))
                key += items
            if typed:
                key += tuple(type(v) for v in args)
                if kwargs:
                    key += tuple(type(v) for _, v in items)
            return key

        def wrapper(*args, **kwargs):
            key = make_key(args, kwargs)
            now = timer()
            if key in cache:
                val, expire = cache[key]
                # Check TTL
                if expire is None or expire > now:
                    # Move to end of LRU list
                    try:
                        lru.remove(key)
                    except ValueError:
                        pass
                    lru.append(key)
                    return val
                # Expired: remove
                del cache[key]
                try:
                    lru.remove(key)
                except ValueError:
                    pass

            # Compute new value
            val = func(*args, **kwargs)
            expire = None if ttl <= 0 else now + ttl
            cache[key] = (val, expire)
            lru.append(key)

            # Enforce maxsize
            if maxsize > 0 and len(cache) > maxsize:
                oldest = lru.pop(0)
                cache.pop(oldest, None)

            return val

        def cache_clear():
            nonlocal cache, lru
            cache = {}
            lru = []

        wrapper.cache_clear = cache_clear
        return wrapper

    return decorator

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.

    """

    def decorator(fn):
        cache = {}
        from collections import OrderedDict
        cache = OrderedDict()

        def key_func(*args, **kwargs):
            key = args
            if kwargs:
                # sorted items to make the order deterministic
                key += tuple(sorted(kwargs.items()))
            if typed:
                key += tuple(type(arg) for arg in args)
                if kwargs:
                    key += tuple(type(v) for _, v in sorted(kwargs.items()))
            return key

        @wraps(fn)
        def wrapper(*args, **kwargs):
            k = key_func(*args, **kwargs)
            try:
                return cache[k]
            except KeyError:
                pass
            result = fn(*args, **kwargs)
            cache[k] = result
            if len(cache) > maxsize:
                cache.popitem(last=False)
            return result

        wrapper.cache = cache
        wrapper.cache_clear = cache.clear
        return wrapper

    return decorator

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    try:
        key, value = next(iter(self.items()))
    except StopIteration:
        raise KeyError('popitem(): dictionary is empty')
    del self[key]
    return key, value

