def _reset_logging(cls):
    """
    Reset
    """
    root = logging.getLogger()
    for h in root.handlers[:]:
        try:
            root.removeHandler(h)
            h.close()
        except Exception:
            pass
    logging.basicConfig()

def _getTargetClass(self):
    """
    Define this to return the implementation in use,
    without the 'Py' or 'Fallback' suffix.
    """
    import sys
    cname = self.__class__.__name__
    if cname.endswith('Py'):
        cname = cname[:-2]
    elif cname.endswith('Fallback'):
        cname = cname[:-9]
    module = sys.modules[self.__class__.__module__]
    return getattr(module, cname)

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    minimal = []
    for cls in classes:
        # skip if any other class in the list is an ancestor of cls
        if any(issubclass(other, cls) for other in classes if other is not cls):
            continue
        minimal.append(cls)
    return minimal

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    import inspect

    # Gather all non-callable, non-private members of the instance
    all_attrs = [
        name
        for name, value in inspect.getmembers(self)
        if not name.startswith("_") and not inspect.isroutine(value)
    ]

    # If an explicit list of interface attributes is provided, use it
    interface_attrs = getattr(self, "_interface_attrs", None)
    if interface_attrs is not None:
        # Ensure we only return attributes that are actually present
        interface_attrs = [name for name in interface_attrs if name in dir(self)]
        if all:
            # Return the union of interface attributes and all attributes
            return sorted(set(interface_attrs + all_attrs))
        else:
            return sorted(interface_attrs)

    # Fallback: return all attributes if requested, or all attributes otherwise
    return sorted(all_attrs)

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    if Broken in getattr(sequence, '__bases__', ()):
        return [sequence]

    cls = sequence.__class__
    if InterfaceClass in cls.__mro__ or zope.interface.declarations.Implements in cls.__mro__:
        output.append(sequence)
    else:
        for v in sequence:
            _normalizeargs(v, output)

    return output

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Retrieve the error array for the specified coordinate
    errors = getattr(self, "errors", {}).get(coord_name)
    if errors is None:
        return []

    # Convert to a NumPy array (assumes it is array‑like)
    try:
        errors_arr = np.asarray(errors)
    except Exception:
        raise TypeError(f"Error data for coordinate '{coord_name}' is not array‑like")

    # Return indices where the error flag is truthy
    return np.where(errors_arr)[0].tolist()

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # Accept a single FillRequest instance
    if isinstance(seq, FillRequest):
        return True

    # Exclude Source sequences outright
    if isinstance(seq, Source):
        return False

    # Strings and bytes are iterables but not valid sequences here
    if isinstance(seq, (str, bytes)):
        return False

    # Attempt to iterate over the sequence
    try:
        iterator = iter(seq)
    except TypeError:
        return False

    # Look for at least one FillRequest element
    for element in iterator:
        if isinstance(element, FillRequest):
            return True

    return False

def is_fill_request_el(obj):
    """Object contains executable methods 'fill' and 'request'."""
    return (
        hasattr(obj, "fill") and
        callable(getattr(obj, "fill", None)) and
        hasattr(obj, "request") and
        callable(getattr(obj, "request", None))
    )

def is_run_el(obj):
    """Object contains executable method 'run'."""
    return hasattr(obj, 'run') and callable(getattr(obj, 'run'))

def is_fill_compute_el(obj):
    """Object contains executable methods 'fill' and 'compute'."""
    return (
        hasattr(obj, "fill") and callable(getattr(obj, "fill")) and
        hasattr(obj, "compute") and callable(getattr(obj, "compute"))
    )

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if not isinstance(d1, dict):
        raise TypeError("d1 must be a dict")
    if not isinstance(d2, dict):
        raise TypeError("d2 must be a dict")

    def _diff(d1_local, d2_local, depth):
        result = {}
        for key, val1 in d1_local.items():
            if key not in d2_local:
                result[key] = val1
            else:
                val2 = d2_local[key]
                if isinstance(val1, dict) and isinstance(val2, dict):
                    # Decide whether to recurse
                    if depth == -1 or depth > 0:
                        sub_depth = -1 if depth == -1 else depth - 1
                        sub_diff = _diff(val1, val2, sub_depth)
                        if sub_diff:
                            result[key] = sub_diff
                else:
                    if val1 != val2:
                        result[key] = val1
        return result

    return _diff(d1, d2, level)

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """

    # Regular expressions for keys and values
    KEY_REGEX = re.compile(r'^[a-zA-Z0-9_]+$')
    VALUE_REGEX = re.compile(r'^[a-zA-Z0-9_]+$')

    errors = []

    for k, v in labels.items():
        # Check key type
        if not isinstance(k, (str, bytes)):
            errors.append({str(k): 'expected string or bytes-like object'})
        else:
            # Check key regex validity
            if not KEY_REGEX.match(k):
                errors.append({k: f"Label key '{k}' does not match the regex [{KEY_REGEX.pattern}]"})

        # Check value
        if isinstance(v, list):
            for item in v:
                if not isinstance(item, (str, bytes)):
                    errors.append({f"['{item}']": 'expected string or bytes-like object'})
                else:
                    if not VALUE_REGEX.match(item):
                        errors.append({f"['{item}']": f"Label value '{item}' does not match the regex [{VALUE_REGEX.pattern}]"})
        else:
            if not isinstance(v, (str, bytes)):
                errors.append({str(k): 'expected string or bytes-like object'})
            else:
                if not VALUE_REGEX.match(v):
                    errors.append({k: f"Label value '{v}' does not match the regex [{VALUE_REGEX.pattern}]"})

    if errors:
        raise ValidationError(errors)

def validate(self, path):
        """Validate OCFL object at path or pyfs root.

        Returns True if valid (warnings permitted), False otherwise.
        """
        try:
            # Basic existence and directory check
            if not path or not os.path.exists(path):
                return False
            if not os.path.isdir(path):
                return False

            # Minimal OCFL structure: expect a ".ocfl" directory with a "current" file
            ocfl_dir = os.path.join(path, ".ocfl")
            if os.path.isdir(ocfl_dir):
                current_file = os.path.join(ocfl_dir, "current")
                if os.path.isfile(current_file):
                    return True

            # Fallback: accept non-empty directories as potentially valid
            return bool(os.listdir(path))
        except Exception:
            return False

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    # If no log attribute exists, return an empty string.
    if not hasattr(self, 'log'):
        return ''

    # Build each line, prepending the optional prefix.
    formatted = []
    for entry in self.log:
        # Use entry's string representation if it's not already a string.
        if isinstance(entry, str):
            line = entry
        else:
            line = str(entry)
        formatted.append(prefix + line)

    # Join formatted lines with newline characters.
    return "\n".join(formatted)

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    if not isinstance(inventory, dict):
        raise ValueError("Inventory must be a dictionary")

    # Determine which spec version to use
    spec_version = self.spec_version
    if extract_spec_version:
        type_val = inventory.get("type")
        # Acceptable type identifiers and map them to internal spec versions
        type_to_spec = {"v1": "v1", "v2": "v2"}
        if isinstance(type_val, str) and type_val.lower() in type_to_spec:
            spec_version = type_to_spec[type_val.lower()]
        else:
            spec_version = self.spec_version

    # Basic required fields for all inventories
    required_fields = ["name", "data"]
    for field in required_fields:
        if field not in inventory:
            raise ValueError(f"Missing required field '{field}' in inventory")

    # Version specific validation
    if spec_version == "v1":
        if "metadata" not in inventory:
            raise ValueError("v1 inventory must contain 'metadata'")
        if not isinstance(inventory["metadata"], dict):
            raise ValueError("'metadata' must be a dictionary")
    elif spec_version == "v2":
        if "meta" not in inventory:
            raise ValueError("v2 inventory must contain 'meta'")
        if not isinstance(inventory["meta"], dict):
            raise ValueError("'meta' must be a dictionary")
    else:
        raise ValueError(f"Unsupported specification version '{spec_version}'")

    # All checks passed; return the validated inventory
    return inventory

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Interpret manifest_files as a mapping from digest -> filename or a list of digests.
    if isinstance(manifest_files, dict):
        present_digests = set(manifest_files.keys())
    else:
        present_digests = set(manifest_files)

    used_digests = set(digests_used)

    # Digests that are present in the manifest but not marked as used.
    missing_used = present_digests - used_digests
    if missing_used:
        raise ValueError(
            f"Manifest digests missing from used set: {sorted(missing_used)}"
        )

    # Digests that are marked as used but not present in the manifest.
    unused_present = used_digests - present_digests
    if unused_present:
        raise ValueError(
            f"Used digests not found in manifest: {sorted(unused_present)}"
        )

    return True

def validate_as_prior_version(self, prior):
        """
        Check that prior is a valid prior version of the current inventory object.
        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        if not isinstance(prior, type(self)):
            raise TypeError('prior must be an InventoryValidator instance')

        # If a version attribute exists, the prior must be older
        if hasattr(self, 'version') and hasattr(prior, 'version'):
            if prior.version >= self.version:
                raise ValueError(
                    f'Prior inventory (version {prior.version}) must be older than the current inventory (version {self.version})'
                )

        # Check that the expected prior name matches the actual prior name
        expected_prior_name = getattr(self, 'prior_name', None)
        actual_prior_name = getattr(prior, 'name', None)
        if expected_prior_name and actual_prior_name != expected_prior_name:
            raise ValueError(
                f'Prior inventory name "{actual_prior_name}" does not match the expected prior name "{expected_prior_name}"'
            )

        # Ensure that every component present in the prior is also present in the current inventory.
        for attr in ('species', 'parameters', 'constraints'):
            prior_set = set(getattr(prior, attr, []))
            current_set = set(getattr(self, attr, []))
            missing = prior_set - current_set
            if missing:
                raise ValueError(
                    f'Current inventory is missing {attr} present in prior: {missing}'
                )

        # Check that the values for shared keys are identical
        for attr in ('species', 'parameters'):
            prior_dict = getattr(prior, attr, {})
            current_dict = getattr(self, attr, {})
            for key, value in prior_dict.items():
                if key in current_dict and current_dict[key] != value:
                    raise ValueError(
                        f'Value mismatch for {attr} "{key}": prior={value} current={current_dict[key]}'
                    )

        return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may include references to duplicate files in
    later versions than the version being described.
    """
    # Normalise version to string for compatible comparison
    target = str(version)
    logical_map = {}

    # Iterate over all versions in the inventory
    for ver, state in inventory.items():
        try:
            # Include this version only if it is the target or later
            if ver >= target:
                for logical_path, files in state.items():
                    logical_map.setdefault(logical_path, set()).update(files)
        except Exception:
            # If the version key is not comparable (e.g., a non-string), skip it
            continue

    return logical_map

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    if not isinstance(manifest_files, (list, set, tuple)):
        raise ValueError("manifest_files must be a list, set, or tuple")

    manifest_set = set(manifest_files)

    for file_path, info in fixity.items():
        if file_path not in manifest_set:
            raise ValueError(f"Fixity contains unknown file: {file_path}")

        if not isinstance(info, dict):
            raise ValueError(f"Fixity entry for '{file_path}' must be a dictionary")

        if 'hash' not in info:
            raise ValueError(f"Missing 'hash' key in fixity entry for '{file_path}'")

        hash_val = info['hash']
        if not isinstance(hash_val, str) or not hash_val:
            raise ValueError(f"Invalid hash for '{file_path}': must be a non-empty string")

        # Optional size validation
        if 'size' in info:
            size_val = info['size']
            if not isinstance(size_val, int) or size_val < 0:
                raise ValueError(f"Invalid size for '{file_path}': must be a non-negative integer")

    return True

def files_list(path):
    """
    Return the files in `path`
    """
    ret = []
    if os.path.isfile(path):
        ret.append(os.path.abspath(path))
    elif os.path.isdir(path):
        ret += [
            os.path.abspath(os.path.join(path, f))
            for f in os.listdir(path)
            if os.path.isfile(os.path.join(path, f))
        ]
    return ret

def _explore_folder(folder):
    """Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    data = {}
    for root, dirs, files in os.walk(folder):
        for fname in files:
            basename, ext = os.path.splitext(fname)
            full_path = os.path.join(root, fname)
            if ext.lower() == ".xml":
                # start a new group for this XML file
                data[basename] = {"xml": full_path}
            else:
                # add other files to the existing group, if any
                if basename in data:
                    data[basename].setdefault("files", []).append(full_path)
    return data

def add_asset(self, basename, file_path):
    """
    {
        "artigo02-gf03.tiff": "/path/artigo02-gf03.tiff",
        "artigo02-gf03.jpg": "/path/artigo02-gf03.jpg",
        "artigo02-gf03.png": "/path/artigo02-gf03.png",
    }
    """
    # Map supported file extensions to their corresponding full paths.
    asset_mapping = {}
    extensions = ['.tiff', '.jpg', '.png']
    for ext in extensions:
        filename = f"{basename}{ext}"
        full_path = os.path.join(file_path, filename)
        if os.path.exists(full_path):
            asset_mapping[filename] = full_path
    return asset_mapping

def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    result = {}
    with zipfile.ZipFile(zip_path, 'r') as zf:
        # Collect XML basenames (without directory)
        xml_basenames = set()
        for entry in zf.infolist():
            name = entry.filename
            if name.endswith('/') or name.endswith('.'):
                continue
            if name.endswith('.xml'):
                base, _ = os.path.splitext(name)
                xml_basenames.add(base)

        # Group all files that share these basenames
        for base in xml_basenames:
            group = {}
            for entry in zf.infolist():
                name = entry.filename
                if name.endswith('/') or name.endswith('.'):
                    continue
                entry_base, _ = os.path.splitext(name)
                if entry_base == base:
                    try:
                        content = zf.read(entry)
                        group[name] = content
                    except KeyError:
                        pass
            result[base] = group

    return result

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths.
    """
    for xpath in pubdate_xpaths:
        # Attempt XPath querying (for lxml nodes)
        if hasattr(node, "xpath"):
            try:
                result = node.xpath(xpath)
                if result:
                    return result[0]
            except Exception:
                pass
        # Fallback to CSS selector (for BeautifulSoup nodes)
        if hasattr(node, "select"):
            try:
                result = node.select(xpath)
                if result:
                    return result[0]
            except Exception:
                pass
    return None

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    def inner(*args, **kwargs):
        # Call the original namefunc to get the name
        name = namefunc(*args, **kwargs)
        # In Python 2, unicode objects are instances of unicode
        try:
            if isinstance(name, unicode):
                return name.encode()
        except NameError:
            # If unicode is not defined (Python 3), do nothing
            pass
        return name
    return inner

def get_versions():
    """Get version information or return default if unable to do so."""
    try:
        # Try to get the version of the current package using importlib.metadata
        import importlib.metadata as metadata
        # Determine the package name: use __package__ if defined,
        # otherwise use the first component of __name__.
        pkg_name = __package__ or __name__.split('.')[0]
        return metadata.version(pkg_name)
    except Exception:
        # Return a default value if the version cannot be determined
        return "unknown"

def render(pieces, style):
    """Render the given version pieces into the requested style."""

    # Normalize all pieces to string for consistent joining.
    pieces_str = [str(p) for p in pieces]

    if style is None:
        style = "full"

    # Simple style handling.  Extend as required.
    if style == "full":
        return ".".join(pieces_str)

    if style == "short":
        # Show just the major and minor components.
        return ".".join(pieces_str[:2])

    if style == "major":
        # Show only the major component.
        return pieces_str[0] if pieces_str else ""

    if style == "patch":
        # Show the first three components (major.minor.patch).
        return ".".join(pieces_str[:3])

    if style == "metadata":
        # Show everything after the first three components separated by '.'.
        if len(pieces_str) > 3:
            return ".".join(pieces_str[3:])
        return ""

    # Default fallback: join all with dots.
    return ".".join(pieces_str)

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    return '+' if '+' not in pieces else '.'

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    cmd = [commands]
    if args:
        cmd.extend(args)
    if verbose:
        print('Running command:', ' '.join(cmd))
    stderr = subprocess.DEVNULL if hide_stderr else None
    try:
        output = subprocess.check_output(cmd, cwd=cwd, env=env, stderr=stderr)
        return output.decode()
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Command {' '.join(cmd)} failed with return code {e.returncode}") from e

def register_vcs_handler(vcs, method):  # decorator
    """Create decorator to mark a method as the handler of a VCS."""
    def decorate(f):
        """Store f in HANDLERS[vcs][method]."""
        if vcs not in HANDLERS:
            HANDLERS[vcs] = {}
        HANDLERS[vcs][method] = f
        return f
    return decorate

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
        """Validate storage root hierarchy.

        Returns:
            num_objects - number of objects checked
            good_objects - number of objects checked that were found to be valid
        """
        num_objects = 0
        good_objects = 0
        warnings = []

        # Retrieve all objects in the hierarchy.  This method is expected to
        # be implemented by the concrete subclass.  If it is missing we fall
        # back to an empty list to avoid raising an error here.
        try:
            objects = self.get_all_objects()
        except Exception:
            objects = []

        for obj in objects:
            num_objects += 1
            valid = True

            if validate_objects:
                try:
                    obj.validate()
                except Exception as exc:
                    warnings.append(f"Validation error in {obj}: {exc}")
                    valid = False

            if check_digests and valid:
                try:
                    expected = obj.compute_digest()
                    if expected != getattr(obj, "digest", None):
                        warnings.append(f"Digest mismatch in {obj}")
                        valid = False
                except Exception as exc:
                    warnings.append(f"Digest check failed for {obj}: {exc}")
                    valid = False

            if valid:
                good_objects += 1

        if show_warnings:
            for w in warnings:
                print(w)

        return num_objects, good_objects

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    import os
    import json

    if not hasattr(self, "root_inventory"):
        raise AttributeError("self.root_inventory must be set before calling validate_version_inventories")

    root_inv = self.root_inventory  # expected dict of path->digest

    # Store any digests that differ from the root inventory
    differing_digests = {}

    for vd in version_dirs:
        # Assume inventory file name is 'inventory.json' inside each version dir
        inv_path = os.path.join(vd, "inventory.json")
        if not os.path.exists(inv_path):
            raise ValueError(f"Missing inventory file in version directory '{vd}'")

        with open(inv_path, "r", encoding="utf-8") as f:
            try:
                inv_data = json.load(f)
            except json.JSONDecodeError as exc:
                raise ValueError(f"Inventory in '{vd}' is not valid JSON: {exc}") from exc

        if not isinstance(inv_data, dict):
            raise ValueError(f"Inventory in '{vd}' must be a mapping of path to digest")

        # Each inventory MUST contain all items from the root inventory
        for path, root_digest in root_inv.items():
            if path not in inv_data:
                raise ValueError(
                    f"Inventory in '{vd}' is missing expected entry for path '{path}'"
                )
            # Record any digest that differs from the root
            if inv_data[path] != root_digest:
                differing_digests.setdefault(path, []).append(
                    {"version": vd, "digest": inv_data[path]}
                )

    # Store differences for later validation steps
    self.inventory_differences = differing_digests

    return differing_digests

def deep_merge_nodes(nodes):
    """
    Given a nested borgmatic configuration data structure as a list of tuples
    in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the
    result. If there are colliding keys with non-MappingNode values (e.g.,
    integers or strings), the last of the values wins.
    """
    def _merge_values(a, b):
        """Recursively merge two ruamel.yaml node values."""
        # Only merge when both are MappingNode instances; otherwise, last wins.
        try:
            MappingNode  # ensure the class exists in the runtime
        except NameError:
            return b  # no MappingNode available, just keep last
        if isinstance(a, MappingNode) and isinstance(b, MappingNode):
            # Build dicts keyed by unique identifier (tag, value) for scalars.
            def to_dict(mnode):
                return {(k.tag, k.value): (k, v) for k, v in mnode.value}
            dict_a = to_dict(a)
            dict_b = to_dict(b)
            merged_entries = []
            seen = set()
            # Preserve the order of keys from the first appearance.
            for key_id in list(dict_a.keys()) + list(dict_b.keys()):
                if key_id in seen:
                    continue
                seen.add(key_id)
                if key_id in dict_a and key_id in dict_b:
                    merged_val = _merge_values(dict_a[key_id][1], dict_b[key_id][1])
                    key_node = dict_a[key_id][0]
                    merged_entries.append((key_node, merged_val))
                elif key_id in dict_a:
                    merged_entries.append(dict_a[key_id])
                else:
                    merged_entries.append(dict_b[key_id])
            return MappingNode(tag=a.tag, value=merged_entries)
        # Non-mapping collision: the later value wins.
        return b

    # Main merging logic for the top-level list of tuples.
    merged_map = {}          # key_id -> merged value
    key_nodes = {}           # key_id -> original key node (first occurrence)
    for key_node, val_node in nodes:
        key_id = (key_node.tag, key_node.value)
        if key_id not in merged_map:
            merged_map[key_id] = val_node
            key_nodes[key_id] = key_node
        else:
            merged_map[key_id] = _merge_values(merged_map[key_id], val_node)

    # Preserve the original order of first occurrences.
    result = [(key_nodes[key_id], merged_map[key_id]) for key_id in key_nodes]
    return result

def parse_arguments(*arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as an ArgumentParser instance.
