    return ' '.join(flags)

def deep_merge_nodes(nodes):
    """
    Deep merge a list of YAML (ruamel) node pairs.
    """
    def is_mapping(node):
        # True if node is a MappingNode
        return getattr(node, "tag", "").startswith("tag:yaml.org,2002:map")

    def merge_values(old_value, new_value):
        # Merge two node values respecting MappingNodes
        if is_mapping(old_value) and is_mapping(new_value):
            merged_pairs = merge_pairs(old_value.value + new_value.value)
            # Return a new MappingNode with the new node's tag
            return type(new_value)(new_value.tag, merged_pairs)
        # If the new value is a mapping, it wins
        if is_mapping(new_value):
            return new_value
        # Otherwise, the new value wins
        return new_value

    def merge_pairs(pair_list):
        """
        Merge a list of (key_node, value_node) pairs.
        Preserves order of first occurrence of each key.
        """
        acc = {}
        order = []
        for k_node, v_node in pair_list:
            key = k_node.value
            if key in acc:
                # Merge values for duplicate subkeys
                acc[key] = (k_node, merge_values(acc[key][1], v_node))
            else:
                acc[key] = (k_node, v_node)
                order.append(key)
        return [(acc[k][0], acc[k][1]) for k in order]

    # First combine all top‑level nodes preserving order
    acc = {}
    order = []
    for k_node, v_node in nodes:
        key = k_node.value
        if key in acc:
            acc[key] = (k_node, merge_values(acc[key][1], v_node))
        else:
            acc[key] = (k_node, v_node)
            order.append(key)

    # Build final result list
    result = []
    for key in order:
        result.append(acc[key])
    return result

