def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    for d in dicts:
        for key, value in d.items():
            if key in result:
                result[key] += value
            else:
                result[key] = value
    return result

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    if not url or not url_args:
        return url

    for key, value in url_args.items():
        placeholder = "{" + str(key) + "}"
        if placeholder in url:
            try:
                # Percent-encode the value to keep URL valid
                encoded_value = urllib.parse.quote(str(value), safe='')
            except Exception:
                encoded_value = str(value)
            url = url.replace(placeholder, encoded_value)

    return url

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    if val is None:
        return True
    if isinstance(val, str):
        stripped = val.strip()
        if not stripped:
            return True
        if stripped.lower() in ("none", "null", "na", "n/a"):
            return True
    return False

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    flags = []
    seen = set()
    for action in parser._actions:
        for opt in action.option_strings:
            if opt not in seen:
                seen.add(opt)
                flags.append(opt)
    return " ".join(flags)

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    return value.replace('.', arg)

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    seen = set()
    queue = {cls}
    while queue:
        c = queue.pop()
        seen.add(c)
        subcs = c.__subclasses__()
        for subc in subcs:
            if subc not in seen:
                queue.add(subc)
    seen.discard(cls)
    return seen

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not alphabet:
        raise ValueError("alphabet must not be empty")
    base = len(alphabet)
    inv = {ch: i for i, ch in enumerate(alphabet)}
    n = 0
    for ch in string:
        if ch not in inv:
            raise ValueError(f"Character {ch!r} not in alphabet")
        n = n * base + inv[ch]
    return n

def unquote(name):
    """Remove quote from the given name."""
    if len(name) > 1:
        # Handle double quoted strings
        if name.startswith('"') and name.endswith('"'):
            return name[1:-1].replace('\\\\', '\\').replace('\\"', '"')
        # Handle angle brackets
        if name.startswith('<') and name.endswith('>'):
            return name[1:-1]
        # Handle single quoted strings
        if name.startswith("'") and name.endswith("'"):
            return name[1:-1]
    return name

def addignored(ignored):
    ''' Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''
    try:
        output = subprocess.check_output(
            ['git', 'ls-files', '--others', '--ignored', '--exclude-standard'],
            stderr=subprocess.STDOUT
        )
    except subprocess.CalledProcessError:
        return ''
    files = output.decode().splitlines()
    # Remove empty lines and strip whitespace
    files = [f.strip() for f in files if f.strip()]
    files.sort()
    return ','.join(files)

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    # Quick checks for common localhost representations
    common_local = {
        'localhost',
        '127.0.0.1',
        '::1',
        'localhost.localdomain',
        'localhost6',
        'ip6-localhost',
    }
    if host in common_local:
        return True
    try:
        # Resolve the host and inspect all returned addresses
        for res in socket.getaddrinfo(host, None):
            family, _, _, _, sockaddr = res
            ip = sockaddr[0]
            if family == socket.AF_INET:
                # Any 127.x.x.x address is considered loopback for IPv4
                if ip == '127.0.0.1' or ip.startswith('127.'):
                    return True
            elif family == socket.AF_INET6:
                # ::1 is the only standard loopback for IPv6
                if ip == '::1':
                    return True
    except socket.gaierror:
        # Host could not be resolved; not localhost
        pass
    return False

