def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    if dumper is None:
        dumper = yaml.SafeDumper
    # `yaml.safe_dump` returns a unicode string on Python 2
    # and a text string on Python 3, which satisfies the requirement.
