def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    def _merge_dicts(target, override):
        for key, value in override.items():
            if key in target and isinstance(target[key], dict) and isinstance(value, dict):
                _merge_dicts(target[key], value)
            else:
                target[key] = value
        return target

    def _resolve_env(cfg):
        import os
        if isinstance(cfg, dict):
            return {k: _resolve_env(v) for k, v in cfg.items()}
        elif isinstance(cfg, list):
            return [_resolve_env(v) for v in cfg]
        elif isinstance(cfg, str):
            # replace ${VAR} patterns
            import re
            pattern = re.compile(r'\$\{([^}]+)\}')
            def repl(match):
                return os.getenv(match.group(1), '')
            return pattern.sub(repl, cfg)
        else:
            return cfg

    configs = {}
    error_records = []
    for fn in config_filenames:
        try:
            with open(fn, 'r') as f:
                raw = f.read()
            if fn.endswith('.toml'):
                import toml
                cfg = toml.loads(raw)
            elif fn.endswith(('.yaml', '.yml')):
                import yaml
                cfg = yaml.safe_load(raw)
            elif fn.endswith('.json'):
                import json
                cfg = json.loads(raw)
            else:
                raise ValueError(f'Unsupported config file extension: {fn}')
            if not isinstance(cfg, dict):
                raise TypeError(f'Config in {fn} is not a dictionary')
            if resolve_env:
                cfg = _resolve_env(cfg)
            if overrides:
                cfg = _merge_dicts(cfg, overrides)
            configs[fn] = cfg
        except Exception as e:
            record = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=fn,
                lineno=0,
                msg=f'Error parsing {fn}: {e}',
                args=(),
                exc_info=None
            )
            record.exc_info = (type(e), e, e.__traceback__)
            error_records.append(record)
    return configs, error_records

def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    # Gather all handler classes from the subclass that expose a
    # PROTOCOL_INFO attribute (typically a tuple like (major, minor)).
    handlers = {}
    for obj in cls.__dict__.values():
        if isinstance(obj, type) and hasattr(obj, "PROTOCOL_INFO"):
            version = getattr(obj, "PROTOCOL_INFO")
            # Ensure the version attribute is a tuple; skip otherwise.
            if isinstance(version, tuple):
                handlers[version] = obj

    # If a specific protocol version is requested, filter the dictionary.
    if protocol_version is not None:
        if not isinstance(protocol_version, tuple):
            raise TypeError("protocol_version must be a tuple identifying the protocol")
        handler = handlers.get(protocol_version)
        return {protocol_version: handler} if handler else {}

    # Return a copy of the full handlers dictionary when no version
    # was requested.
    return dict(handlers)

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq* (or is *seq*, if that is of a sequence type).
    """
    # Immediate mapping for common built‑in sequence types
    if isinstance(seq, (str, bytes)):
        return seq, type(seq)
    if isinstance(seq, (list, tuple)):
        return seq, type(seq)

    # Handle file‑like objects: read the contents
    if hasattr(seq, "read"):
        data = seq.read(bufsize) if bufsize is not None else seq.read()
        return data, type(data)

    # Handle any other iterable: consume it into a list
    if hasattr(seq, "__iter__"):
        seq_list = list(seq)
        return seq_list, type(seq_list)

    raise TypeError("Cannot derive a sequence from %r" % (seq,))

def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    errors = []

    # 1. Check interface provision (if not tentative)
    if not tentative:
        try:
            provided = iface.providedBy(candidate)
        except Exception:
            provided = False
        if not provided:
            errors.append(
                f"candidate does not provide interface {iface!r}"
            )

    # 2. Gather potential methods and attributes from the interface
    try:
        interface_members = iface.__dict__
    except AttributeError:
        interface_members = {}

    # Distinguish methods and attributes
    import inspect

    interface_methods = {
        name: obj
        for name, obj in interface_members.items()
        if callable(obj) and not name.startswith("__")
    }
    interface_attrs = {
        name: val
        for name, val in interface_members.items()
        if not callable(val) and not name.startswith("__")
    }

    # 3. Validate methods
    for name, iface_method in interface_methods.items():
        candidate_attr = getattr(candidate, name, None)
        if candidate_attr is None:
            errors.append(f"candidate missing method '{name}'")
            continue
        if not callable(candidate_attr):
            errors.append(f"candidate attribute '{name}' is not callable")
            continue
        try:
            iface_sig = inspect.signature(iface_method)
            cand_sig = inspect.signature(candidate_attr)
        except Exception:
            # If signature inspection fails, skip detailed comparison
            continue
        # Compare parameter names and count, ignoring 'self' if present
        iface_params = [
            p for p in iface_sig.parameters.values()
            if p.name != "self"
        ]
        cand_params = [
            p for p in cand_sig.parameters.values()
            if p.name != "self"
        ]
        if len(iface_params) != len(cand_params) or \
           [p.name for p in iface_params] != [p.name for p in cand_params]:
            errors.append(
                f"signature mismatch for method '{name}': "
                f"expected {iface_sig}, got {cand_sig}"
            )

    # 4. Validate attributes
    for name in interface_attrs:
        if not hasattr(candidate, name):
            errors.append(f"candidate missing attribute '{name}'")

    # 5. Raise or return
    if errors:
        if len(errors) == 1:
            raise zope.interface.Invalid(errors[0])
        else:
            msg = "Multiple interface errors: " + "; ".join(errors)
            raise zope.interface.Invalid(msg)
    return True

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    # If an explicit metaclass is given, use it
    if explicit_mc is not None:
        return explicit_mc

    # No bases: default to the built‑in type
    if not bases:
        return type

    # Gather the metaclasses of all base classes
    mcs = set(type(b) for b in bases)

    # Single metaclass case – just return it
    if len(mcs) == 1:
        return mcs.pop()

    # Find a candidate that is a subclass of all other metaclasses
    for candidate in mcs:
        if all(issubclass(candidate, other) or candidate == other for other in mcs):
            return candidate

    # If no such metaclass exists, raise an error
    raise TypeError("metaclass conflict: no common metaclass found")

def pop(self, key, default=__marker):
    """D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    try:
        value = self[key]
    except KeyError:
        if default is __marker:
            raise
        return default
    del self[key]
    return value

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not self._cache:
        raise KeyError('dict is empty')
    min_key = None
    min_freq = None
    for key in self._cache:
        freq = self._freq.get(key, 0)
        if min_freq is None or freq < min_freq:
            min_freq = freq
            min_key = key
    value = self._cache.pop(min_key)
    self._freq.pop(min_key, None)
    return (min_key, value)

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    return self._cache.popitem(last=True)

def popitem(self):
    """Remove and return a random `(key, value)` pair."""
    import random
    if not self:
        raise KeyError('popitem from an empty dict')
    key = random.choice(list(self.keys()))
    value = self.pop(key)
    return (key, value)

def _create_converter(self) -> _converting._Converter:
    """Create the parameter style converter.

    Returns the parameter style converter (:class:`._converting._Converter`).
    """
    return _converting._Converter()

def parse(self, timestr, default=None, ignoretz=False, tzinfos=None, **kwargs):
    """Parse the date/time string into a :class:`datetime.datetime` object."""

    # Delegate to dateutil's parser
    from dateutil.parser import parse as _parse
    return _parse(timestr, default=default, ignoretz=ignoretz, tzinfos=tzinfos, **kwargs)

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Private encrypted JSON payload
    try:
        data = json.loads(decode_if_bytes(request.body))
        if "encrypted_magic_envelope" in data:
            return True
    except Exception:
        pass
    # Public XML payload
    try:
        xml = etree.fromstring(encode_if_text(request.body))
        if xml.tag == MAGIC_ENV_TAG:
            return True
    except Exception:
        pass
    return False

def format_dt(dt):
    """Format a datetime in the way that D* nodes expect."""
    # Ensure datetime is timezone aware; if not, assume UTC
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=datetime.timezone.utc)
    # Convert to UTC and format as ISO 8601 without fractional seconds
    return dt.astimezone(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    import re

    # Regex to match URLs starting with http:// or https://
    url_pattern = re.compile(r"(https?://[^\s]+)")

    def replace_link(match):
        url = match.group(0)
        # Default attributes to add; can be overridden by setting a callback
        default_attrs = 'target="_blank"'
        # Check if a custom callback has been attached to the function
        custom_attrs = ''
        if hasattr(process_text_links, "_link_attrs_callback"):
            try:
                retval = process_text_links._link_attrs_callback(url)
                if retval:
                    custom_attrs = f" {retval}"
            except Exception:
                # Silently ignore errors from the callback to avoid breaking the linkification
                custom_attrs = ''
        attrs = custom_attrs or f" {default_attrs}"
        return f'<a href="{url}"{attrs}>{url}</a>'

    return url_pattern.sub(replace_link, text)

def fetch_content_type(url: str) -> Optional[str]:
    """Fetch the HEAD of the remote url to determine the content type."""
    try:
        # Build a HEAD request
        req = request.Request(url, method='HEAD')
        # Perform the request
        with request.urlopen(req) as resp:
            # Retrieve the Content-Type header if present
            return resp.getheader('Content-Type')
    except Exception:
        # On any error (network, missing headers, etc.) return None
        return None

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    if not isinstance(tag, str) or not tag:
        return False
    allowed_chars = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-")
    return all(c in allowed_chars for c in tag)

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    result = {}
    for child in node:
        result[child.tag] = child
    return result

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Default to the standard NodeInfo path if no custom path is supplied
    if document_path:
        path = document_path
    else:
        path = "/.well-known/nodeinfo/1.0"

    # Ensure no double slashes when concatenating
    base = url.rstrip("/")
    full_uri = f"{base}{path}"

    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/1.0",
                "href": full_uri
            }
        ]
    }

def parse_diaspora_webfinger(document: str) -> Dict:
    """Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    result = {}
    # Try JSON format first
    try:
        data = json.loads(document)
        links = data.get("links", [])
        for link in links:
            rel = link.get("rel")
            href = link.get("href") or link.get("template")
            if rel and href:
                if rel == "hcard":
                    result["hcard_url"] = href
                else:
                    result[rel] = href
        result["subject"] = data.get("subject")
        result["aliases"] = data.get("aliases", [])
        return result
    except Exception:
        pass

    # Fallback to XRD (XML) format
    try:
        root = ET.fromstring(document)
    except Exception:
        return result

    for elem in root.iter():
        tag = elem.tag.lower()
        if tag.endswith("link"):
            rel = elem.attrib.get("rel")
            href = elem.attrib.get("href") or elem.attrib.get("template")
            if rel and href:
                if rel == "hcard":
                    result["hcard_url"] = href
                else:
                    result[rel] = href
    return result

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        host = handle.split('@')[1]
    except Exception:
        return None

    # Construct the WebFinger URL using HTTPS first
    url = 'https://{}/.well-known/webfinger?resource=acct:{}'.format(host, quote(handle))

    try:
        with urllib2.urlopen(url) as response:
            if response.getcode() == 200:
                return response.read()
    except Exception:
        # Fallback to HTTP if HTTPS fails
        url = 'http://{}/.well-known/webfinger?resource=acct:{}'.format(host, quote(handle))
        try:
            with urllib2.urlopen(url) as response:
                if response.getcode() == 200:
                    return response.read()
        except Exception:
            return None

    return None

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    try:
        host = handle.split("@")[1]
    except AttributeError:
        logger.warning("retrieve_and_parse_diaspora_webfinger: invalid handle given: %s", handle)
        return None
    document, code, exception = fetch_document(
        host=host, path="/.well-known/webfinger?resource=acct:%s" % quote(handle),
    )
    if document:
        return parse_diaspora_webfinger(document)
    hostmeta = retrieve_diaspora_host_meta(host)
    if not hostmeta:
        return None
    url = hostmeta.find_link(rels="lrdd").template.replace("{uri}", quote(handle))
    document, code, exception = fetch_document(url)
    if exception:
        return None
    return parse_diaspora_webfinger(document)

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    # Ensure settings_dirs is a list
    if isinstance(settings_dirs, str):
        settings_dirs = [settings_dirs]
    try:
        files = []
        for directory in settings_dirs:
            for fname in os.listdir(directory):
                if fname.endswith(spec_option):
                    files.append(os.path.join(directory, fname))
        return sorted(files)
    except OSError:
        return []

def ansible_config_manager(cls):
    """Gets the ansible config manager."""
    try:
        from ansible.constants import Config
    except Exception as exc:
        raise ImportError(f"Cannot import Ansible Config: {exc}")
    return Config()

def workspace_manager(cls):
    """Gets the workspace manager. """
    if not hasattr(cls, "_workspace_manager"):
        cls._workspace_manager = WorkspaceManager()
    return cls._workspace_manager

def plugins_manager(cls):
    """Gets the plugin manager. """
    if not hasattr(cls, "_plugin_manager"):
        cls._plugin_manager = PluginManager()
    return cls._plugin_manager

def validate_from_content(cls, spec_content=None):
        """validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data
        is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """
        if spec_content is None:
            raise IRValidatorException("No spec content provided")

        # If the content is a string assume YAML and load it
        if isinstance(spec_content, str):
            try:
                spec_data = yaml.safe_load(spec_content)
            except Exception as e:
                raise IRValidatorException(f"Error parsing spec content: {e}") from e
        elif isinstance(spec_content, dict):
            spec_data = spec_content
        else:
            raise IRValidatorException(f"Unsupported spec content type: {type(spec_content)}")

        # Determine required fields (class may define a list of required keys)
        required_fields = getattr(cls, "REQUIRED_FIELDS", [])
        missing = [field for field in required_fields if field not in spec_data]
        if missing:
            raise IRValidatorException(
                f"Missing mandatory fields in spec: {', '.join(missing)}"
            )
        return spec_data

def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """

    if yaml_file is None:
        raise IRValidatorException("yaml_file argument must be supplied")

    if not hasattr(yaml_file, "open"):
        yaml_file = Path(yaml_file)

    try:
        with yaml_file.open() as f:
            data = yaml.safe_load(f)
    except FileNotFoundError as e:
        raise IRValidatorException(f"File not found: {yaml_file}") from e
    except Exception as e:
        raise IRValidatorException(f"Error loading YAML file: {e}") from e

    if data is None:
        raise IRValidatorException("YAML file contains no data")

    required = getattr(cls, "REQUIRED_FIELDS", None)
    if required:
        missing = [field for field in required if field not in data]
        if missing:
            raise IRValidatorException(
                f"Mandatory fields missing in the YAML file: {', '.join(missing)}"
            )
    return data

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    for arg in self.args:
        # Only handle option objects
        if not isinstance(arg, _BaseOpt):
            continue

        # Resolve from spec if present, otherwise use the option's default
        if hasattr(self, "spec") and arg.name in self.spec:
            defaults[arg.name] = self.spec[arg.name]
        elif not isinstance(arg.default, NoDefault):
            defaults[arg.name] = arg.default

        # If the option is a dictionary type with an internal scheme,
        # recurse to gather nested defaults.
        if isinstance(arg, DictOption) and arg.scheme:
            nested = arg.scheme.get_spec_defaults()
            if nested:
                defaults[arg.name] = nested

    return defaults

def get_deprecated_args(self):
    """Returning dict with options which deprecate others. """
    return {}

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    if not hasattr(self, "_commands"):
        raise AttributeError("Parser options have not been initialized (missing _commands)")
    try:
        command = self._commands[command_name]
    except KeyError as exc:
        raise KeyError(f"Unknown command name: {command_name}") from exc
    # The command entry is expected to have an 'options' key holding a list.
    options = command.get("options")
    if options is None:
        raise ValueError(f"Command '{command_name}' does not define an 'options' list")
    if not isinstance(options, list):
        raise TypeError(f"Command '{command_name}' options should be a list, got {type(options).__name__}")
    return options

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    spec = self._option_specs.get(command_name, {}).get(argument_name)
    if spec is None:
        raise KeyError(
            f"Option spec for command '{command_name}' and argument '{argument_name}' not found"
        )
    return spec

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    required = getattr(self, 'required_args', None)
    if required is None:
        # If no explicit list, assume all keys in args are required
        return
    for name in required:
        if name not in args or args[name] is None:
            raise InvalidArgumentError(f"Missing required argument: {name}")

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    for arg_name, arg_attrs in args.items():
        # Get the maximum allowed length, if any
        max_len = arg_attrs.get("max_length")
        if max_len is None:
            continue

        # Ensure the max_len is a non‑negative integer
        if not isinstance(max_len, int):
            raise TypeError(
                f"max_length for argument '{arg_name}' must be an int, got {type(max_len).__name__}"
            )
        if max_len < 0:
            raise ValueError(
                f"max_length for argument '{arg_name}' must be non‑negative, got {max_len}"
            )

        # Retrieve the argument value to validate
        value = arg_attrs.get("value")
        if value is None:
            continue

        # Only strings, containers and sequences can be measured for length
        try:
            value_len = len(value)
        except Exception:
            continue

        if value_len > max_len:
            raise ValueError(
                f"Length of argument '{arg_name}' ({value_len}) exceeds "
                f"maximum allowed ({max_len})."
            )

def validate_choices_args(self, args):
    """
    Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # `self.choices` is expected to be a mapping from argument name to
    # an iterable of allowed values.
    if not hasattr(self, 'choices') or not self.choices:
        return

    for name, value in args.items():
        if value is None:
            continue  # skip unset optional arguments
        if name in self.choices:
            valid = self.choices[name]
            if value not in valid:
                valid_list = list(valid)
                msg = (
                    f"Invalid value for '{name}': {value!r}. "
                    f"Must be one of: {valid_list}"
                )
                raise ValueError(msg)

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments, which can be either a
                 three-element tuple/list ``(value, min_, max_)``, a
                 dictionary with keys ``'value'``, ``'min'`` and
                 ``'max'``, or an iterable of such items.

    :return: The original argument(s) if all values are within the
             specified ranges.
    :raise ValueError: If any value is outside its range.
    :raise TypeError: If the argument format is not recognized.
    """
    def _check_single(item):
        if isinstance(item, (list, tuple)) and len(item) == 3:
            value, min_, max_ = item
        elif isinstance(item, dict):
            if not {'value', 'min', 'max'}.issubset(item):
                raise TypeError("Dictionary must contain 'value', 'min', and 'max'")
            value = item['value']
            min_ = item['min']
            max_ = item['max']
        else:
            raise TypeError("Item must be a 3-element sequence or a dict with 'value', 'min', 'max'")
        if min_ is not None and value < min_:
            raise ValueError(f"Value {value} is less than minimum {min_}")
        if max_ is not None and value > max_:
            raise ValueError(f"Value {value} is greater than maximum {max_}")
        return item

    if isinstance(args, (list, tuple)):
        if len(args) == 3 and not isinstance(args[0], (list, tuple, dict)):
            # Single item
            return _check_single(args)
        else:
            # Iterable of items
            return [_check_single(item) for item in args]
    elif isinstance(args, dict):
        return _check_single(args)
    else:
        raise TypeError("Arguments must be a dict, a 3-element list/tuple, or an iterable of such items.")

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}

    # Normalize args to an iterable of key/value pairs.
    # Accept a list of tuples, dictionary, or list of strings.
    def _iter_args(arg_list):
        if isinstance(arg_list, dict):
            for k, v in arg_list.items():
                yield k, v
        elif isinstance(arg_list, list):
            for item in arg_list:
                if isinstance(item, tuple) and len(item) == 2:
                    yield item[0], item[1]
                elif isinstance(item, str):
                    # Treat a lone string as a flag with a boolean True
                    yield item, True
                else:
                    # Skip unrecognized formats
                    continue
        else:
            # Unsupported type, yield nothing
            return

    for key, value in _iter_args(args):
        # Normalize key to a string if not already
        if not isinstance(key, str):
            continue
        if key.startswith('control_'):
            # Strip the prefix for clarity, but keep the full key for use
            control_args[key] = value
        elif key.startswith('custom_'):
            # Convert custom variable to nested format by removing the prefix
            nested_key = key[len('custom_') :]
            nested_args[nested_key] = value
        else:
            nested_args[key] = value

    return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``.

    :param vars_dict: Dictionary to merge extra-vars into.
    :param extra_vars: List of extra-vars (or a single dict) that will be merged
                       into ``vars_dict``. Keys in ``extra_vars`` override
                       those in ``vars_dict``.
    """
    if not isinstance(vars_dict, dict):
        raise ValueError("`vars_dict` must be a dictionary")

    if extra_vars is None:
        # Nothing to merge; return the original dictionary.
        return vars_dict

    # If a single dictionary is provided, merge it directly.
    if isinstance(extra_vars, dict):
        vars_dict.update(extra_vars)
        return vars_dict

    # If a sequence (list/tuple) is provided, merge each individual dictionary.
    if isinstance(extra_vars, (list, tuple)):
        for elem in extra_vars:
            if isinstance(elem, dict):
                vars_dict.update(elem)
            else:
                raise ValueError(
                    "Each element of `extra_vars` must be a dictionary"
                )
        return vars_dict

    # Unsupported type for extra_vars.
    raise ValueError(
        "`extra_vars` must be a dict, a list, or a tuple of dicts"
    )

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    command = ["ansible-playbook"]

    if verbose:
        # Add verbosity flags (e.g., -vvv)
        command.append("-" + "v" * verbose)

    if ansible_args:
        for key, val in ansible_args.items():
            if val is True:
                command.append(f"--{key}")
            elif val is False:
                # skip false boolean options
                continue
            else:
                command.append(f"--{key}={val}")

    if extra_vars:
        try:
            import json
            extra_vars_str = json.dumps(extra_vars)
        except Exception:
            extra_vars_str = str(extra_vars)
        command.extend(["--extra-vars", extra_vars_str])

    command.append(playbook_path)

    # Determine where to execute the playbook
    cwd = None
    if hasattr(ir_workspace, "root"):
        cwd = ir_workspace.root
    elif hasattr(ir_workspace, "path"):
        cwd = ir_workspace.path

    result = subprocess.run(command, capture_output=True, text=True, cwd=cwd)

    if result.returncode != 0:
        raise RuntimeError(f"ansible-playbook failed with return code {result.returncode}:\n{result.stderr}")

    return result.stdout

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Mapping from parser_name to argument specifications.
    # Each spec is a dict mapping argument names to a type or a callable
    # that knows how to convert a string value.
    # Example:
    #   {
    #       'main': {'port': int, 'debug': bool, 'hosts': list, 'config': Path},
    #       'virsh': {...}
    #   }
    # The actual mapping is expected to be defined elsewhere in the class.
    specs = getattr(self, "_arg_specs", {})

    # If we have no specifications for this parser, nothing to do.
    if parser_name not in specs:
        return values_dict

    # Retrieve the arg spec for this parser.
    arg_spec = specs[parser_name]

    for arg_name, convert_func in arg_spec.items():
        if arg_name not in values_dict:
            continue
        raw_value = values_dict[arg_name]

        # If raw_value is already not a string, skip conversion.
        if not isinstance(raw_value, str):
            continue

        # Determine the conversion function.
        # If convert_func is a type (e.g., int, float), use it directly.
        # If it has a 'convert' method, use that.
        # Otherwise, try calling it as a callable.
        converter = None
        if isinstance(convert_func, type):
            converter = convert_func
        elif hasattr(convert_func, "convert"):
            converter = convert_func.convert
        elif callable(convert_func):
            converter = convert_func

        # Perform the conversion if a converter is found.
        if converter is not None:
            try:
                # For booleans, handle common string representations.
                if converter is bool:
                    values_dict[arg_name] = raw_value.lower() in ("true", "1", "yes", "y")
                else:
                    values_dict[arg_name] = converter(raw_value)
            except Exception:
                # If conversion fails, keep the original string value.
                values_dict[arg_name] = raw_value

    return values_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    spec_files = ['plugin.json', 'plugin.yml', 'plugin.yaml']
    spec_path = None
    for f in spec_files:
        full_path = os.path.join(plugin_dir, f)
        if os.path.isfile(full_path):
            spec_path = full_path
            break

    if not spec_path:
        return {}

    # Load the spec file into a dictionary
    try:
        with open(spec_path, 'r', encoding='utf-8') as fp:
            if spec_path.endswith('.json'):
                import json
                spec_data = json.load(fp)
            else:
                # For yaml/yml assume yaml module is already available
                import yaml
                spec_data = yaml.safe_load(fp)
    except Exception:
        return {}

    def _flatten(d, parent_key=''):
        flat = {}
        for k, v in d.items():
            key = f"{parent_key}.{k}" if parent_key else k
            if isinstance(v, dict):
                flat.update(_flatten(v, key))
            elif isinstance(v, list):
                for idx, item in enumerate(v):
                    sub_key = f"{key}.{idx}"
                    if isinstance(item, dict):
                        flat.update(_flatten(item, sub_key))
                    else:
                        flat[sub_key] = item
            else:
                flat[key] = v
        return flat

    return _flatten(spec_data)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    import os
    env_var = "CONFIG_PATH"
    if env_var not in os.environ:
        os.environ[env_var] = str(self.config_path)

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("Both 'path' and 'root' must be strings")
    # Normalize the paths to absolute form
    root_norm = os.path.abspath(root)
    path_norm = os.path.abspath(path)
    # Ensure the path actually starts with the root
    if not path_norm.startswith(root_norm):
        raise ValueError(f"Path '{path}' does not start with the root '{root}'")
    # Strip the root prefix
    stripped = path_norm[len(root_norm):]
    # Remove any leading separator that may remain
    if stripped.startswith(os.sep):
        stripped = stripped[len(os.sep):]
    return stripped}
